			text = [=[Anduin's grandfather, King {link:llane-wrynn}Llane Wrynn{/link}, died in the fall of the old {link:stormwind-city}Stormwind{/link}. His father grew up in exile at the court of {link:terenas-menethil}King Terenas{/link} in {link:lordaeron}Lordaeron{/link} and returned to build a new city. His mother, Queen {link:tiffin-wrynn}Tiffin{/link}, died in its streets. Anduin has inherited both the crown and its wounds.]=],
		},
	},
	bonds = {
		{ id = "varian-wrynn", name = "Varian Wrynn", note = "his father, missing" },
		{ id = "tiffin-wrynn", name = "Tiffin Wrynn", note = "his mother" },
