			hint = "Carry the plea of Lakeshire to Stormwind Keep.",
			unlock = {
				{ type = "quest", id = 4185 },
			},
			text = [=[When {link:lakeshire}Lakeshire{/link} begged the crown for help in {link:redridge-mountains}Redridge{/link}, the regent would not answer until Lady Prestor had spoken. She heard the plea and gave her counsel. Only then did {link:bolvar-fordragon}Bolvar{/link} write his decree.]=],
		},
		{
			key = "the-great-masquerade",
			title = "The Great Masquerade",
			hint = "See the court of Stormwind as it truly is.",
			unlock = {
				{ type = "quest", id = 6403 },
			},
			text = [=[When Marshal {red:reginald-windsor}Reginald Windsor{/red} came to the throne room with his proof, Lady Prestor mocked him and called for his arrest. Then she cast off her disguise. Lady Katrana Prestor had never been a noblewoman at all. She was {link:onyxia}Onyxia{/link}, daughter of {link:deathwing}Deathwing{/link}, a black dragon who had worn a human face in the court of {link:stormwind-city}Stormwind{/link}. For as long as she stood beside the regent, the black dragonflight had held the ear of the kingdom. Windsor died in the throne room. Onyxia fled, and she left {link:bolvar-fordragon}Bolvar{/link} to learn how long he had been her puppet.]=],
