	sections = {
		{
			title = "Summary",
			text = [=[Lord Grayson Shadowbreaker trains the paladins of {link:stormwind-city}Stormwind{/link} in the halls of the {link:cathedral-of-light}Cathedral of Light{/link}. He is a knight and a teacher, and his students learn from him that the {link:holy-light}Holy Light{/link} asks for sacrifice before it grants strength. The young paladins of the kingdom pass through his hands, and so do the old ones when they seek a harder road.]=],
		},
		{
			title = "Significance",
			text = [=[{link:captain-grayson}Grayson{/link} keeps alive the union of faith and steel that the Church of the {link:holy-light}Holy Light{/link} forged after the {link:first-war}First War{/link}. His counsel reaches beyond {link:stormwind-city}Stormwind{/link}. He sends young paladins of the dwarves to their own teachers in {link:ironforge}Ironforge{/link}, and he is trusted with holy things that the kingdom wishes to keep safe.]=],
		},
		{
			title = "Deeds",
			text = [=[• He trains the paladins of the Cathedral.
• He sends dwarven paladins to Tiza Battleforge in {link:ironforge}Ironforge{/link}.
• He sets the proven paladins of the realm on a long road of trials and sacrifice.
• He receives the Menethil Statuette for safekeeping in the Cathedral.]=],
		},
		{
			title = "Unrecorded",
			text = [=[Little is written of {link:captain-grayson}Grayson{/link}'s life before the Cathedral, nor of the deeds that earned him his title.]=],
