			unlock = {
				{ type = "quest", id = 98191 },
			},
			text = [=[King {link:terenas-menethil}Terenas Menethil{/link} was a humble man who disliked monuments, and few likenesses of him survived the fall of his kingdom. When a small statue of him came out of the {link:wetlands}Wetlands{/link}, the Light seemed to rest within it. It was carried to {link:stormwind-city}Stormwind{/link} and placed in Lord {link:captain-grayson}Grayson{/link}'s keeping, to be guarded in the {link:cathedral-of-light}Cathedral of Light{/link}.]=],
		},
		{
			key = "the-road-of-sacrifice",
			title = "The Road of Sacrifice",
			hint = [=[Walk the long road that Lord Grayson sets before the paladins of the realm.]=],
			unlock = {
				{ type = "quest", id = 7637 },
			},
			text = [=[{link:captain-grayson}Grayson{/link} does not grant a paladin's honors lightly. The first trial he sets is one of sacrifice: a costly gift to the church of {link:ironforge}Ironforge{/link}, in exchange for a holy censer kept by its high priest.]=],
